mapper.sql:
WITH surgery_stats AS ( SELECT asset_uid, COALESCE(SUM(usage_count)::INTEGER, 0) AS total_usage_count, ROUND(COALESCE(SUM(usage_duration), 0) / 1440.0, 2) AS total_occupation_days, COUNT(DISTINCT NULLIF(operating_room_name, '')) AS operating_room_coverage_count FROM surgery_anesthesia_data_result WHERE tenant_uid = #{tenantUid} AND surgery_date BETWEEN #{startDate}::date AND #{endDate}::date
AND site_uid = #{siteUid}
GROUP BY asset_uid ) SELECT e.uid, e.asset_uid AS "assetUid", COALESCE(e.asset_name, ai.name) AS "assetName", e.display_name AS "displayName", COALESCE(e.function_type, ai.function_type) AS "functionType", COALESCE(e.depart_num, ai.depart_num) AS "departNum", COALESCE(e.serial_num, ai.serial_num) AS "serialNum", COALESCE(e.qr_code, ai.qr_code) AS "qrCode", ai.make_short_name AS "makerShortName", ai.clinical_dept_name AS "clinicalDeptName", ai.asset_group AS "assetGroup", e.positive_rate AS "positiveRate", COALESCE(s.total_usage_count, 0) AS "totalUsageCount", COALESCE(s.total_occupation_days, 0) AS "totalOccupationDays", COALESCE(s.operating_room_coverage_count, 0) AS "operatingRoomCoverageCount" FROM surgery_anesthesia_equipment_info e LEFT JOIN asset_info ai ON e.asset_uid = ai.uid LEFT JOIN surgery_stats s ON e.asset_uid = s.asset_uid WHERE e.tenant_uid = #{tenantUid}
AND e.site_uid = #{siteUid}
AND COALESCE(e.asset_name, ai.name) LIKE concat('%', #{assetName}, '%')
AND e.display_name LIKE concat('%', #{displayName}, '%')
AND COALESCE(e.function_type, ai.function_type) LIKE concat('%', #{functionType}, '%')
AND COALESCE(e.depart_num, ai.depart_num) LIKE concat('%', #{departNum}, '%')
AND COALESCE(e.serial_num, ai.serial_num) LIKE concat('%', #{serialNum}, '%')
AND COALESCE(e.qr_code, ai.qr_code) LIKE concat('%', #{qrCode}, '%')
AND ai.make_short_name LIKE concat('%', #{makerShortName}, '%')
AND ai.clinical_dept_name LIKE concat('%', #{clinicalDeptName}, '%')
AND e.positive_rate >= #{positiveRateGTE}
AND e.positive_rate <= #{positiveRateLTE}

mapper.select:


    ORDER BY ${orderBy}


    ORDER BY e.uid DESC

LIMIT #{pageSize} OFFSET #{offset}
